completion.code:
if (*ppos >= mbox_len) return 0;
size_t n = mbox_len - *ppos;
if (n > count) n = count;
if ({{copy}}(buf, mbox + *ppos, n)) return -EFAULT;
*ppos += {{advance}};
return n;

if (count > MBOX_SIZE) return -{{capacity}};
if ({{copy}}(mbox, buf, count)) return -EFAULT;
mbox_len = {{length}};
return count;

mbox_class = class_create("mailbox");
if ({{check}}(mbox_class)) {
    ret = {{error}}(mbox_class);
    goto err_cdev;
}
/* percorso di errore: classe non acquisita */
err_cdev:
    {{remove}}(&mbox_cdev);
    unregister_chrdev_region(devno, 1);
    return ret;
